    use super::*;

    const _ADD: fn(u64, u64) -> Result<u64> = add_lamports;
    const _SUB: fn(u64, u64) -> Result<u64> = sub_lamports;
    const _AFTER: fn(u64, u64) -> u64 = balance_after_deposit;
    const _SLUG: fn(VaultError) -> &'static str = error_slug;
